var ReactGlobal;
function getActiveVlanOptions(db) {
  let subnets = {};
  try { subnets = getAllSubnets(); } catch (err) { subnets = {}; }
  let vlanMap = new Map();
  Object.entries(subnets || {}).forEach(([vIdStr, info]) => {
    let vId = Number(vIdStr);
    if (!isNaN(vId) && vId > 0 && info && !info._deleted) {
      vlanMap.set(vId, { id: vId, name: info.name || `VLAN ${vId}`, color: info.color || `var(--vlan-${vId})` });
    }
  });
  (db || []).forEach((rack) => {
    (rack.switches || []).forEach((sw) => {
      (sw.conns || []).forEach((conn) => {
        if (conn.v != null && conn.v > 0 && !vlanMap.has(conn.v)) {
          vlanMap.set(conn.v, { id: conn.v, name: `VLAN ${conn.v}`, color: `var(--vlan-${conn.v})` });
        }
      });
    });
  });
  return Array.from(vlanMap.values()).sort((x, y) => x.id - y.id);
}

